import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        StringTokenizer st = new StringTokenizer(br.readLine());
        HashSet<Long> points = new HashSet<>(N * 2);
        points.add(0L);

        long pos = 0;
        long total = 0;

        for (int i = 0; i < N; i++) {
            while (!st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }

            long len = Long.parseLong(st.nextToken());
            pos += len;
            total += len;

            if (i < N - 1) {
                points.add(pos);
            }
        }

        if (total % 2 != 0) {
            System.out.println("N");
            return;
        }

        long target = total / 2;
        long count = 0;

        for (long p : points) {
            long q = p + target;
            if (q >= total) {
                q -= total;
            }

            if (points.contains(q)) {
                count++;
            }
        }

        System.out.println(count >= 4 ? "S" : "N");
    }
}
